import json

def main():
    daytona = Daytona()

    print("Creating sandbox...")
    sandbox = daytona.create()
    print(f"Sandbox id: {sandbox.id}")
    print(f"Sandbox state: {sandbox.state}")

    # Inspect sandbox object
    print("\nSandbox attributes:")
    for attr in dir(sandbox):
        if not attr.startswith('_'):
            try:
                val = getattr(sandbox, attr)
                if not callable(val):
                    print(f"  {attr}: {val}")
            except:
                pass

    # Try to inspect the process API client
    print("\nProcess API client info:")
    try:
        api_client = sandbox._api_client
        print(f"  api_client host: {api_client.configuration.host}")
    except Exception as e:
        print(f"  Error: {e}")

if __name__ == "__main__":
    main()
