{"path": "/home/daytona/cleanup_sandboxes.py", "content": "from daytona import Daytona

def main():
    daytona = Daytona()

    print("Listing sandboxes...")
    sandboxes = list(daytona.list())
    print(f"Found {len(sandboxes)} sandboxes")

    for s in sandboxes:
        print(f"  {s.id} - state={s.state} - cpu={s.cpu} - mem={s.memory}")
        print(f"    Deleting...")
        try:
            daytona.delete(s, wait=True)
            print(f"    Deleted.")
        except Exception as e:
            err_str = str(e)
            if "not found" in err_str.lower():
                print(f"    Already deleted.")
            else:
                print(f"    Error deleting: {e}")

if __name__ == "__main__":
    main()
"}
